def isPrimitive(v):
	return v is None or isinstance(v, (bool, int, long, float, basestring))

def fmt(v):
	if v is None:
		return ""
	if isinstance(v, bool):
		return "true" if v else "false"
	try:
		return str(v)
	except:
		return ""

def escapeMd(s, inTable=False):
	"""
	Escapes markdown-breaking characters.
	If inTable=True, also converts newlines to <br> so a cell can't break the row.
	"""
	if s is None:
		return ""
	try:
		s = str(s)
	except:
		return ""

	s = s.replace("|", "\\|") 		# Pipes break markdown tables

	s = s.replace("\r\n", "\n").replace("\r", "\n")		# Normalize newlines

	if inTable: s = s.replace("\n", "<br>") 	# In tables, newlines break the row -> convert to <br>

	return s

def titleize(key):
	if key is None:
		return ""
	try:
		key = str(key)
	except:
		return ""
	out = []
	buf = ""
	for ch in key:
		if ch == "_":
			if buf:
				out.append(buf)
				buf = ""
			continue
		if ch.isupper() and buf:
			out.append(buf)
			buf = ch
		else:
			buf += ch
	if buf: out.append(buf)
	return " ".join([w[:1].upper() + w[1:] for w in out if w])

def looksLikeJson(s):
	if not isinstance(s, basestring):	return False
	t = s.strip()
	return (t.startswith("{") and t.endswith("}")) or (t.startswith("[") and t.endswith("]"))

def scanJsonValue(s, start):
	i = start
	while i < len(s) and s[i].isspace():
		i += 1
	if i >= len(s):	return None, None

	openCh = s[i]
	if openCh not in ["{", "["]: return None, None

	closeCh = "}" if openCh == "{" else "]"
	depth = 0
	inStr = False
	esc = False
	j = i

	while j < len(s):
		ch = s[j]
		if inStr:
			if esc:	esc = False
			elif ch == "\\": esc = True
			elif ch == '"':	inStr = False
		else:
			if ch == '"': inStr = True
			elif ch == openCh: 	depth += 1
			elif ch == closeCh:
				depth -= 1
				if depth == 0:
					return i, j + 1
		j += 1

	return None, None

def repairAndDecodeJson(text):
	if text is None: return None
	s = text.strip()

	try:
		return system.util.jsonDecode(s)
	except:
		pass

	for key in ["components", "routing", "qualityChecks"]:
		pattern = '"' + key + '":'
		pos = s.find(pattern)
		if pos < 0: continue

		vStart = pos + len(pattern)
		while vStart < len(s) and s[vStart].isspace():
			vStart += 1

		if vStart >= len(s) or s[vStart] != "{": continue

		oStart, oEnd = scanJsonValue(s, vStart)
		if oStart is None: 	continue

		after = s[oEnd:].lstrip()
		if not after.startswith(",{"): continue

		cursor = oEnd
		itemsEnd = oEnd

		while True:
			tmp = s[cursor:].lstrip()
			lead = len(s[cursor:]) - len(tmp)
			cursor += lead

			if cursor < len(s) and s[cursor] == ",": cursor += 1
			else: break

			while cursor < len(s) and s[cursor].isspace():
				cursor += 1

			if cursor >= len(s) or s[cursor] != "{": break

			nStart, nEnd = scanJsonValue(s, cursor)
			if nStart is None: 	break
			itemsEnd = nEnd
			cursor = nEnd

		original = s[vStart:itemsEnd]
		s = s[:vStart] + "[" + original + "]" + s[itemsEnd:]

	return system.util.jsonDecode(s)

def normalize(v, depth=0, seen=None):
	if seen is None: seen = set()
	if depth > maxDepth: return v

	if isinstance(v, basestring) and looksLikeJson(v):
		try:
			return normalize(system.util.jsonDecode(v), depth + 1, seen)
		except:
			return v

	if isinstance(v, dict):
		if id(v) in seen: return v
		seen.add(id(v))
		return {k: normalize(v.get(k), depth + 1, seen) for k in v}

	if isinstance(v, (list, tuple)):
		return [normalize(x, depth + 1, seen) for x in v]

	return v

def unionKeys(dicts):
	keys = []
	seenK = set()
	for d in dicts:
		if not isinstance(d, dict): continue
		for k in d:
			if k not in seenK:
				seenK.add(k)
				keys.append(k)
			if len(keys) >= maxTableKeys: return keys
	return keys

def renderTable(rows, keys):
	"""
	IMPORTANT: Markdown tables must start at column 0.
	So we intentionally do NOT indent these lines.
	"""
	lines = []
	lines.append("| " + " | ".join(titleize(k) for k in keys) + " |")
	lines.append("| " + " | ".join("---" for _ in keys) + " |")

	for r in rows:
		cells = []
		for k in keys:
			val = r.get(k)
			cells.append("[...]" if isinstance(val, (dict, list)) else fmt(val))
		lines.append("| " + " | ".join(escapeMd(c, inTable=True) for c in cells) + " |")
	return lines

maxDepth = 6
maxItems = 50
maxTableKeys = 20

title = ''
lines = []
seen = set()
obj = normalize(json)

def walk(v, key=None, depth=0):
	if depth > maxDepth:
		lines.append(("  " * depth) + "_(max depth reached)_")
		return

	if isinstance(v, (dict, list)):
		if id(v) in seen:
			lines.append(("  " * depth) + "_(circular reference)_")
			return
		seen.add(id(v))

	# Use spaces, not tabs, to avoid accidental code blocks
	indent = "  " * depth

	if isPrimitive(v):
		if key is not None: lines.append(indent + "- **%s:** %s" % (titleize(key), escapeMd(fmt(v))))
		return

	if isinstance(v, dict):
		if key is not None:
			lines.append(("## " if depth == 0 else "### ") + titleize(key))
			lines.append("")
		for k in sorted(v):
			if isPrimitive(v[k]):
				walk(v[k], k, depth)
		nested = [k for k in v if not isPrimitive(v[k])]
		if nested: lines.append("")
		for k in sorted(nested):
			walk(v[k], k, depth + 1)
		lines.append("")
		return

	if isinstance(v, list):
		if key is not None:
			lines.append(("## " if depth == 0 else "### ") + titleize(key))
			lines.append("")

		items = v[:maxItems]
		if not items:
			lines.append("_(empty)_")
			lines.append("")
			return

		if all(isinstance(i, dict) for i in items):
			keys = unionKeys(items)
			lines.extend(renderTable(items, keys))
			lines.append("")
			return

		for i in items:
			lines.append(indent + "- " + escapeMd(fmt(i)))
		lines.append("")
		return

if title:
	lines.append("# " + title)
	lines.append("")

walk(obj)

while lines and lines[-1] == "":
	lines.pop()

return "\n".join(lines)

